<?php require_once __DIR__ . '/../Arquivos/verificarAdmin.php';require_once __DIR__ . '/../Arquivos/conexao.php';$id=(int)($_POST['id']??0);$imagem=$_POST['imagem_atual']??'';if(!empty($_FILES['imagem']['name'])&&$_FILES['imagem']['error']===UPLOAD_ERR_OK){$ext=strtolower(pathinfo($_FILES['imagem']['name'],PATHINFO_EXTENSION));if(in_array($ext,['jpg','jpeg','png','webp'])){$imagem=uniqid('produto_',true).'.'.$ext;move_uploaded_file($_FILES['imagem']['tmp_name'],__DIR__.'/../Uploads/Produtos/'.$imagem);}}try{$pdo->beginTransaction();$vals=[(int)$_POST['categoria_id'],trim($_POST['nome']),trim($_POST['autor']),trim($_POST['editora']),trim($_POST['isbn'])?:null,trim($_POST['descricao']),(float)$_POST['preco'],$imagem,isset($_POST['ativo'])?1:0];if($id){$vals[]=$id;$pdo->prepare('UPDATE produtos SET categoria_id=?,nome=?,autor=?,editora=?,isbn=?,descricao=?,preco=?,imagem=?,ativo=? WHERE id=?')->execute($vals);}else{$pdo->prepare('INSERT INTO produtos(categoria_id,nome,autor,editora,isbn,descricao,preco,imagem,ativo) VALUES(?,?,?,?,?,?,?,?,?)')->execute($vals);$id=(int)$pdo->lastInsertId();}$pdo->prepare('INSERT INTO estoque(produto_id,quantidade) VALUES(?,?) ON DUPLICATE KEY UPDATE quantidade=VALUES(quantidade)')->execute([$id,max(0,(int)$_POST['quantidade'])]);$pdo->commit();flash('sucesso','Produto salvo.');}catch(Throwable $e){if($pdo->inTransaction())$pdo->rollBack();flash('erro','Erro ao salvar: '.$e->getMessage());}header('Location: produtos.php');exit;